test("workspace restore rejects malformed graphs instead of returning unsafe data", () => {
  assert.equal(parseWorkspacePayload("{}"), null);
  assert.equal(
    parseWorkspacePayload(
      JSON.stringify({
        graph: {
          nodes: [{ id: "a", label: "A", kind: "not-a-kind" }],
          edges: [],
          revision: 1,
        },
      }),
    ),
    null,
  );
  assert.equal(
    parseWorkspacePayload(
      JSON.stringify({
        graph: {
          nodes: [{ id: "a", label: "A", kind: "iri" }],
          edges: [{ id: "e", source: "a", predicate: "urn:p", label: "p", target: "missing" }],
          revision: 1,
        },
      }),
    ),
    null,
  );
});

test("workspace restore rejects predicates that cannot be safely interpolated", () => {
  const restored = parseWorkspacePayload(
    JSON.stringify({
      graph: {
        nodes: [
          { id: "urn:a", label: "A", kind: "iri" },
          { id: "urn:b", label: "B", kind: "iri" },
        ],
        edges: [
          {
            id: "e",
            source: "urn:a",
            predicate: "urn:bad>\nFILTER(false)",
            label: "bad",
            target: "urn:b",
          },
        ],
        revision: 1,
      },
    }),
  );
  assert.equal(restored, null);
});

