test("workspace restore migrates legacy literal node IDs without orphaning edges", () => {
  const restored = parseWorkspacePayload(
    JSON.stringify({
      graph: {
        nodes: [
          { id: "urn:a", label: "A", kind: "iri" },
          {
            id: "5",
            label: "5",
            kind: "literal",
            datatype: "http://www.w3.org/2001/XMLSchema#integer",
          },
        ],
        edges: [
          {
            id: "e",
            source: "urn:a",
            predicate: "urn:value",
            label: "value",
            target: "5",
          },
        ],
        revision: 1,
      },
      selectedNodeIds: ["5"],
      focusedNodeId: "5",
    }),
  );

  assert.ok(restored);
  const migratedId = sparqlNodeId({
    type: "typed-literal",
    value: "5",
    datatype: "http://www.w3.org/2001/XMLSchema#integer",
  });
  assert.ok(restored.graph.nodes.some((node) => node.id === migratedId));
  assert.equal(restored.graph.edges[0].target, migratedId);
  assert.deepEqual(restored.selectedNodeIds, [migratedId]);
  assert.equal(restored.focusedNodeId, migratedId);
});

