test("the graph scope is kept with the graph; one that is not a scope is dropped", () => {
  const payload = (scope) =>
    JSON.stringify({
      graph: { nodes: [{ id: "urn:a", label: "A", kind: "iri" }], edges: [], revision: 1 },
      scope,
    });
  assert.equal(parseWorkspacePayload(payload("urn:ex:graph")).scope, "urn:ex:graph");
  assert.equal(parseWorkspacePayload(payload("all")).scope, "all");
  assert.equal(parseWorkspacePayload(payload("urn:bad> } INSERT")).scope, undefined);
  assert.equal(parseWorkspacePayload(payload(undefined)).scope, undefined);
});

import { mergeTriples } from "../../../main/frontend/graph-explorer/graph-operations.ts";
import { bindingsToTriples } from "../../../main/frontend/graph-explorer/graph-terms.ts";

test("a stored graph with an empty value or a very long one comes back whole", () => {
  const uri = (value) => ({ type: "uri", value });
  for (const value of ["", "x".repeat(20000), "POLYGON((" + "1 2,".repeat(5000) + "1 2))"]) {
    const graph = mergeTriples(
      { nodes: [], edges: [], revision: 0 },
      bindingsToTriples([
        { source: uri("urn:a"), predicate: uri("urn:p"), target: { type: "literal", value } },
        { source: uri("urn:a"), predicate: uri("urn:q"), target: uri("urn:b") },
      ]),
    );
    const restored = parseWorkspacePayload(JSON.stringify({ graph, transform: { x: 0, y: 0, k: 1 }, query: "" }));
    assert.ok(restored, `a value of ${value.length} characters`);
    assert.equal(restored.graph.nodes.length, 3);
    assert.equal(restored.graph.edges.length, 2);
  }
});

import { mergeStatementLinks, statementLinksOf } from "../../../main/frontend/graph-explorer/statement-links.ts";

test("statements about statements are kept with the graph; unsafe ones reject it", () => {
  const uri = (value) => ({ type: "uri", value });
  const rows = [
    { source: uri("urn:alice"), predicate: uri("urn:knows"), target: uri("urn:bob") },
    {
      source: uri("urn:claim"),
      predicate: uri("http://www.w3.org/1999/02/22-rdf-syntax-ns#reifies"),
      target: { type: "triple", value: { subject: uri("urn:alice"), predicate: uri("urn:knows"), object: uri("urn:bob") } },
    },
  ];
  const graph = mergeStatementLinks(mergeTriples({ nodes: [], edges: [], revision: 0 }, bindingsToTriples(rows)), statementLinksOf(rows));
  const payload = (links) => JSON.stringify({ graph: { ...graph, statementLinks: links }, transform: { x: 0, y: 0, k: 1 }, query: "" });
  const restored = parseWorkspacePayload(payload(graph.statementLinks));
  assert.deepEqual(restored.graph.statementLinks, graph.statementLinks);
  assert.equal(parseWorkspacePayload(payload([{ ...graph.statementLinks[0], predicate: "urn:bad> } DROP ALL" }])), null);
  const orphan = parseWorkspacePayload(payload([{ ...graph.statementLinks[0], source: "urn:missing" }]));
  assert.deepEqual(orphan.graph.statementLinks, [], "a link whose node is gone is dropped");
});
